<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {listings} from '$lib/api';let title=$state(''),wasteType=$state(''),quantity=$state(''),unit=$state('kg'),price=$state(''),location=$state(''),description=$state(''),files=$state<File[]>([]),previews=$state<string[]>([]),status=$state('');function choose(e:Event){const input=e.currentTarget as HTMLInputElement;files=Array.from(input.files||[]);previews=files.map(f=>URL.createObjectURL(f))}async function submit(){status='Uploading…';const data=new FormData();data.append('title',title);data.append('wasteType',wasteType);data.append('quantity',quantity);data.append('unit',unit);data.append('priceSats',price);data.append('location',location);data.append('description',description);files.forEach(f=>data.append('photos',f));try{await listings.create(data);status='Listing created successfully.'}catch(e){status=e instanceof Error?e.message:'Upload failed. Please try again.'}}</script><PageShell eyebrow="FARMER LISTINGS" title="List your surplus."><div class="form-card listing-form"><p class="state">Add clear photos so buyers can check quality before ordering.</p><label>Listing title<input bind:value={title} placeholder="Fresh vegetable trimmings" required /></label><label>Waste type<select bind:value={wasteType}><option value="">Choose type</option><option>Food waste</option><option>Vegetable waste</option><option>Spent grain</option><option>Poultry litter</option></select></label><label>Quantity<input bind:value={quantity} type="number" min="1" /></label><label>Unit<select bind:value={unit}><option>kg</option><option>bags</option><option>tonnes</option></select></label><label>Price (sats / unit)<input bind:value={price} type="number" min="1" /></label><label>Location<input bind:value={location} placeholder="County or town" /></label><label>Description<textarea bind:value={description} rows="4" placeholder="Pickup details, freshness and storage"></textarea></label><label class="upload">Listing photos<input type="file" accept="image/jpeg,image/png,image/webp" multiple onchange={choose}/><small>PNG, JPG or WebP. Multiple photos allowed.</small></label>{#if previews.length}<div class="photo-grid">{#each previews as src}<img src={src} alt="Selected listing preview"/>{/each}</div>{/if}{#if status}<p class="state">{status}</p>{/if}<button class="btn primary" onclick={submit} disabled={!title||!wasteType||!quantity||!price||!location||!files.length||status==='Uploading…'}>{status==='Uploading…'?'Uploading…':'Publish listing ↗'}</button></div></PageShell>
